<?php require_once __DIR__.'/_base.php'; $title='Notifications'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $st=$pdo->prepare('SELECT * FROM notifications WHERE provider_id=? ORDER BY created_at DESC');$st->execute([$u['id']]);?><h2>Notifications</h2><div class="service-card p-3"><?php foreach($st->fetchAll() as $n):?><div class="border-bottom p-3"><b><?=e($n['title'])?></b><p class="mb-1 text-secondary"><?=e($n['message'])?></p><small><?=e($n['created_at'])?></small></div><?php endforeach;?></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>